#include <vector>
#include <unordered_map>
#include <set>

class Solution {
public:
    std::vector<long long> findXSum(std::vector<int>& nums, int k, int x) {
        int n = nums.size();
        std::unordered_map<int, int> counts;
        std::set<std::pair<int, int>> top, bot;
        long long top_sum = 0;

        auto balance = [&]() {
            while (top.size() < x && !bot.empty()) {
                auto it = std::prev(bot.end());
                top_sum += (long long)it->first * it->second;
                top.insert(*it);
                bot.erase(it);
            }
            while (!top.empty() && !bot.empty() && *bot.rbegin() > *top.begin()) {
                auto it_bot = std::prev(bot.end());
                auto it_top = top.begin();
                top_sum -= (long long)it_top->first * it_top->second;
                top_sum += (long long)it_bot->first * it_bot->second;
                auto val_bot = *it_bot;
                auto val_top = *it_top;
                bot.erase(it_bot);
                top.erase(it_top);
                top.insert(val_bot);
                bot.insert(val_top);
            }
        };

        auto add = [&](int v) {
            int old_c = counts[v];
            if (old_c > 0) {
                if (top.count({old_c, v})) {
                    top.erase({old_c, v});
                    top_sum -= (long long)old_c * v;
                } else {
                    bot.erase({old_c, v});
                }
            }
            counts[v]++;
            bot.insert({counts[v], v});
            balance();
        };

        auto remove = [&](int v) {
            int old_c = counts[v];
            if (top.count({old_c, v})) {
                top.erase({old_c, v});
                top_sum -= (long long)old_c * v;
            } else {
                bot.erase({old_c, v});
            }
            counts[v]--;
            if (counts[v] > 0) {
                bot.insert({counts[v], v});
            }
            balance();
        };

        std::vector<long long> ans;
        for (int i = 0; i < k; ++i) add(nums[i]);
        ans.push_back(top_sum);

        for (int i = k; i < n; ++i) {
            add(nums[i]);
            remove(nums[i - k]);
            ans.push_back(top_sum);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public long[] findXSum(int[] nums, int k, int x) {
        int n = nums.length;
        Map<Integer, Integer> counts = new HashMap<>();
        TreeSet<int[]> top = new TreeSet<>((a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(a[1], b[1]);
        });
        TreeSet<int[]> bot = new TreeSet<>((a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(a[1], b[1]);
        });

        long[] topSum = new long[1];

        Runnable balance = () -> {
            while (top.size() < x && !bot.isEmpty()) {
                int[] last = bot.pollLast();
                topSum[0] += (long) last[0] * last[1];
                top.add(last);
            }
            while (!top.isEmpty() && !bot.isEmpty()) {
                int[] t = top.first();
                int[] b = bot.last();
                if (b[0] > t[0] || (b[0] == t[0] && b[1] > t[1])) {
                    top.pollFirst();
                    bot.pollLast();
                    topSum[0] -= (long) t[0] * t[1];
                    topSum[0] += (long) b[0] * b[1];
                    top.add(b);
                    bot.add(t);
                } else {
                    break;
                }
            }
        };

        for (int i = 0; i < k; i++) {
            int v = nums[i];
            int old = counts.getOrDefault(v, 0);
            if (old > 0) {
                int[] p = new int[]{old, v};
                if (!top.remove(p)) bot.remove(p);
                else topSum[0] -= (long) old * v;
            }
            counts.put(v, old + 1);
            bot.add(new int[]{old + 1, v});
            balance.run();
        }

        long[] ans = new long[n - k + 1];
        ans[0] = topSum[0];

        for (int i = k; i < n; i++) {
            int addV = nums[i];
            int addOld = counts.getOrDefault(addV, 0);
            if (addOld > 0) {
                int[] p = new int[]{addOld, addV};
                if (!top.remove(p)) bot.remove(p);
                else topSum[0] -= (long) addOld * addV;
            }
            counts.put(addV, addOld + 1);
            bot.add(new int[]{addOld + 1, addV});
            balance.run();

            int remV = nums[i - k];
            int remOld = counts.get(remV);
            int[] pRem = new int[]{remOld, remV};
            if (!top.remove(pRem)) bot.remove(pRem);
            else topSum[0] -= (long) remOld * remV;

            if (remOld - 1 > 0) {
                counts.put(remV, remOld - 1);
                bot.add(new int[]{remOld - 1, remV});
            } else {
                counts.remove(remV);
            }
            balance.run();

            ans[i - k + 1] = topSum[0];
        }
        return ans;
    }
}

var findXSum = function(nums, k, x) {
    const n = nums.length;
    const counts = new Map();
    // In JavaScript, a sliding window with map and top tracking
    // For n up to 10^5, implement two heaps or sorted array
    // Here we maintain frequency map and sorted list of entries
    let topSum = 0n;
    const ans = [];

    // Simple priority queue helper or insertion sort on active entries
    // Since distinct elements in window <= k
    const distinct = [];
    function recompute() {
        distinct.sort((a, b) => {
            const fa = counts.get(a) || 0;
            const fb = counts.get(b) || 0;
            if (fb !== fa) return fb - fa;
            return b - a;
        });
        let cur = 0n;
        const limit = Math.min(distinct.length, x);
        for (let j = 0; j < limit; j++) {
            const v = distinct[j];
            cur += BigInt(v) * BigInt(counts.get(v));
        }
        return cur;
    }

    for (let i = 0; i < k; i++) {
        const v = nums[i];
        if (!counts.has(v)) distinct.push(v);
        counts.set(v, (counts.get(v) || 0) + 1);
    }
    ans.push(recompute());

    for (let i = k; i < n; i++) {
        const addV = nums[i];
        if (!counts.has(addV) || counts.get(addV) === 0) {
            if (!distinct.includes(addV)) distinct.push(addV);
        }
        counts.set(addV, (counts.get(addV) || 0) + 1);

        const remV = nums[i - k];
        counts.set(remV, counts.get(remV) - 1);
        if (counts.get(remV) === 0) {
            const idx = distinct.indexOf(remV);
            if (idx !== -1) distinct.splice(idx, 1);
        }
        ans.push(recompute());
    }

    return ans.map(Number);
};
